head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.test = function(e) {
    var contentWidth = 800;
    var contentH = 600;
    var bodyWidth = 1280;
    var bodyH = 800;
    var scalePoint = contentWidth / bodyWidth;
    var scalePointH = contentH / bodyH;
    var scaleP = scalePoint <= scalePointH ? scalePoint : scalePointH;
    var scale = 'scale(' + (scaleP) + ')';
    var contentHeight = WebSquare.wUnit.getJq("html").height();
    var bodyHeight = contentHeight / scalePoint;
    var bottomPoint = bodyHeight - contentHeight;
    WebSquare.wUnit.getJq("body").css({
        'position': 'absolute',
        'top': '0',
        'width': '1280px',
        'height': 'initial',
        '-ms-transform': scale,
        'transform': scale,
        'transform-origin': 'top left'
    });
}
scwin.check1 = function() {
    return Math.abs(WebSquare.wUnit.getJq("#sldTest1_thumb1").position().left - WebSquare.wUnit.getJq("#sldTest1_scale_1_1").position().left) < 10 ? true : false;
}
scwin.check2 = function() {
    return Math.abs(WebSquare.wUnit.getJq("#sldTest1_thumb1").position().left - WebSquare.wUnit.getJq("#sldTest1_scale_end_1").position().left) < 10 ? true : false;
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#sldTest1_thumb1').simulate('drag-n-drop', {
        dx: 100,
        dy: 0
    });
}
scwin.setSimulate2 = function() {
    WebSquare.wUnit.getJq('#sldTest1_thumb1').simulate('drag-n-drop', {
        dx: 200,
        dy: 0
    });
}
scwin.setSimulate3 = function() {
    WebSquare.wUnit.getJq('#sldTest1_thumb1').simulate('drag-n-drop', {
        dx: 300,
        dy: 0
    })
}
scwin.setSimulate4 = function() {
    WebSquare.wUnit.getJq('#sldTest1_thumb1').simulate('drag-n-drop', {
        dx: 500,
        dy: 0
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //1. 샘플실행 후 slider 부분을 클릭했을때 원하는 위치로 가거나 drag가 정상동작하는지를 확인한다.
    //1. After running the sample, when you click the slider part, go to the desired position or check whether the drag works properly.
    //WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.check1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //1. slider 부분을 클릭했을때 원하는 위치로 가거나 drag가 정상동작한다.
    //1. When you click the slider part, it moves to the desired position or drag works normally.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate4()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.check2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
